{
  "narrative_summary": "This result rests on the link from Competitive Intensity to Revenue Growth. If competition intensifies beyond current levels, more runs could support a different option. In this model, 72% of runs supported Enter European Market.",
  "story_headlines": {
    "opt_expand": "Enter European Market benefits from a modelled link from market entry through to revenue growth.",
    "opt_wait": "Delay to Next Year would need competitive intensity to rise substantially for more runs to support it."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 91% of variations.",
    "primary_risk": "The link from Competitive Intensity to Revenue Growth is the main sensitivity in this comparison.",
    "stability_factors": [
      "Europe Market Entry shows a well evidenced relationship to Revenue Growth in this model.",
      "Pricing Power contributes positively to Revenue Growth with reasonably firm confidence."
    ],
    "fragility_factors": [
      "The link from Competitive Intensity to Revenue Growth could shift outcomes if intensity rises."
    ]
  },
  "readiness_rationale": "The comparison is settled on your numbers: Europe Market Entry and Pricing Power both support Revenue Growth with firm confidence, and only Competitive Intensity remains an open question worth watching.",
  "evidence_enhancements": {
    "fac_competition": {
      "specific_action": "Commission a short competitive landscape review covering active and likely European entrants in your segment.",
      "rationale": "Competitive Intensity is the main source of sensitivity in this comparison.",
      "evidence_type": "market_research",
      "decision_hygiene": "Estimate your expected competitive intensity before reviewing the research."
    }
  },
  "scenario_contexts": {
    "edge_competition_revenue": {
      "trigger_description": "If Competitive Intensity rises well beyond current levels in the European market...",
      "consequence": "...then the most runs would support Delay to Next Year rather than Enter European Market."
    }
  },
  "flip_thresholds": [
    {
      "factor_id": "fac_competition",
      "factor_label": "Competitive Intensity",
      "current_display": "35%",
      "flip_display": "62%",
      "narrative": "If Competitive Intensity moves from 35% to 62%, more runs would support a different option."
    }
  ],
  "bias_findings": [],
  "key_assumptions": [
    "The link from Europe Market Entry to Revenue Growth assumes current market conditions hold through expansion.",
    "The link from Pricing Power to Revenue Growth assumes pricing power can be maintained as you scale from four hundred to eight hundred pro customers.",
    "Competitive Intensity is modelled at its current level rather than any anticipated rise."
  ],
  "decision_quality_prompts": [
    {
      "question": "What would make you switch to Delay to Next Year?",
      "principle": "Consider-the-opposite",
      "applies_because": "Enter European Market holds a substantial share of supporting runs in this model, so it is worth naming what would overturn that."
    },
    {
      "question": "How will entering the European market feel in 10 minutes, 10 months, and 10 years?",
      "principle": "10-10-10",
      "applies_because": "The expansion decision carries both near-term execution demands and longer-term positioning against Competitive Intensity."
    }
  ],
  "pre_mortem": {
    "failure_scenario": "Enter European Market failed because Competitive Intensity rose faster than modelled, eroding the pricing power Revenue Growth depended on.",
    "warning_signs": [
      "New entrants or aggressive pricing appearing in target European segments.",
      "Pro customer growth stalling well short of the eight hundred target."
    ],
    "mitigation": "Track competitive intensity signals monthly during the first two quarters of entry.",
    "grounded_in": ["edge_competition_revenue", "fac_competition"],
    "review_trigger": "Reconvene if competitive intensity signals rise sharply before the next planning cycle."
  }
}
